	snapshot, err := gpsSnapshot(ctx, opts, repo, flags.head)
	if err != nil {
		return err
	}
	findings := make([]map[string]any, 0)
	for _, spec := range set.Specs {
		for _, anchor := range spec.Anchors {
			found := false
			for _, binding := range set.Bindings {
