 		return true
 	case strings.HasPrefix(trimmed, "VISIT_TYPE("):
 		return true
 	case strings.HasPrefix(trimmed, "SPECIALIZE_MAKE_SIGNED("):
 		return true
 	case strings.HasPrefix(trimmed, "FMT_TYPE_CONSTANT("):
 		return true
 	case strings.HasPrefix(trimmed, "FMT_FORMAT_AS("):
