 		return flags, fmt.Errorf("verify requires --test <command>")
 	}
 	if flags.RecordBaseline == "" && flags.PreEditBaseline == "" {
 		return flags, fmt.Errorf(
 			"verify requires --pre-edit-baseline <path> (or --record-baseline <path> to create one)")
 	}
 	return flags, nil
