 func readVerifyBaseline(path string) (verifyBaseline, error) {
 	content, err := os.ReadFile(path)
 	if err != nil {
 		return verifyBaseline{}, fmt.Errorf("verify could not read --pre-edit-baseline %s: %w", path, err)
 	}
